class Solution {
    public boolean canRepaint(String s, String t, int m) {
        if (s.equals(t)) return true;
        int[] paint = new int[26];
        Arrays.fill(paint, -1);
        for (int i = 0; i < s.length(); i++) {
            int x = s.charAt(i) - 'a', y = t.charAt(i) - 'a';
            if (paint[x] == -1) paint[x] = y;
            else if (paint[x] != y) return false;
        }
        boolean[] used = new boolean[26];
        int distinct = 0;
        for (char c : t.toCharArray()) if (!used[c - 'a']) { used[c - 'a'] = true; distinct++; }
        return distinct < m;
    }
}

