class Solution {
public:
    bool canRepaint(string& s, string& t, int m) {
        if (s == t) return true;
        int paint[26];
        fill(paint, paint + 26, -1);
        for (size_t i = 0; i < s.size(); i++) {
            int x = s[i] - 'a', y = t[i] - 'a';
            if (paint[x] == -1) paint[x] = y;
            else if (paint[x] != y) return false;
        }
        set<char> used(t.begin(), t.end());
        return (int) used.size() < m;
    }
};

