bool canRepaint(char* s, char* t, int m) {
    if (strcmp(s, t) == 0) return true;
    int paint[26];
    for (int x = 0; x < 26; x++) paint[x] = -1;
    for (int i = 0; s[i]; i++) {
        int x = s[i] - 'a', y = t[i] - 'a';
        if (paint[x] == -1) paint[x] = y;
        else if (paint[x] != y) return false;
    }
    int used[26] = {0}, distinct = 0;
    for (int i = 0; t[i]; i++) if (!used[t[i] - 'a']) { used[t[i] - 'a'] = 1; distinct++; }
    return distinct < m;
}
